use app
use core.db as db
use core.http as http
use core.encoding.json as json

struct Ticket {
    id: Int
    title: String
}

struct Load {
    cpu: Float
}

struct Inbox {
    unread: Int
}

fn open_tickets(conn: DBScope, team: String) -[DB.Read]> [Ticket] DBError! {
    rows :: conn.query(SQL{"SELECT id, title FROM ticket WHERE team = {team}"}) ?? return Err(err)
    out := [Ticket]{}
    loop row in rows {
        if db.decode<Ticket>(row) == .Ok(ticket) -> &out.push(ticket)
    }
    Ok(out)
}

fn load(host: String) -[Net]> Load HTTPError! {
    resp :: http.get("http://{host}/load") ?? return Err(err)
    text :: resp.body().text(4096) ?? return Err(err)
    Ok(json.decode<Load>(text) ?? Load{cpu: 0.0})
}

fn run() {
    conn :: db.open_memory()
    // Beginner path: the function is the name and the type.
    tickets :: app.live(open_tickets, conn, "web")      // @Loadable<[Ticket], DBError>
    if tickets == .Loaded(list) -> print("{list.len()} open")
    // Expert path: a source outside the database.
    feed :: app.subscribe(load, "db1", every: 5s)       // @Loadable<Load, HTTPError>
    app.push(load, "db1", value: Load{cpu: 0.4})        // value must be a Load
    app.invalidate(load, "db1")                         // this host fetches again now
    app.invalidate(load)                                // every host fetches again now
    // The number-only helpers become plain writes.
    inbox := @Inbox{unread: 0}
    inbox.unread = 3                                    // changed: readers redraw
    inbox.unread = 3                                    // unchanged: no reader wakes
}

