fn run() {
    msg :: json.parse("{\"id\": 7}") ?? return
    print(foundation_json_integer(&msg.field("id") ?? return))   // 7
}

// Complex: a user program has only the loose reads
use core.encoding.json as json
#Codable
struct Request { id: Int, method: String }

fn show_id(text: String) {
    msg :: json.parse(text) ?? return
    print((&msg.field("id") ?? return).int() ?? -1)
}

fn run() {
    show_id("{\"id\": 7}")                       // 7
    show_id("{\"id\": 7.0}")                     // 7, the loose rule
    show_id("{\"id\": 1e999999}")                // still running after two minutes: a million-digit number
    show_id("{\"id\": 92233720368547758070}")    // 92233720368547758070
    json.decode<Request>("{\"id\": 7.0, \"method\": \"ping\"}") ? r -> print(r.id) ! errors -> print(errors)
    // prints 7: the typed field is loose too
}

