// ===== Simple program =====
// shop/package.jet: the root package (D-PROJECT-ROOT1 D). Static data is the default.
name: "shop"
environments: {
    dev: Environment{
        tools: ["nodejs_22"]
        services: { db: postgres() }
    }
}

// $ cd shop      with `jet env hook` installed: node is on PATH
// $ jet dev      the same, plus db up, then the default dev loop
// No env.jet: nothing else to write.

// ===== Complex program =====
// shop/package.jet: the static default, built from modules.
name: "shop"
deps: { devkit: devkit@jetpack#1 }
environments: {
    dev: Environment{
        include: [team_base(), devkit.node(version: "22")]
        services: { db: postgres(), cache: redis() }
        processes: { web: ["npm", "run", "dev"] }
        vars: { DATABASE_URL: "postgres://127.0.0.1:5432/shop" }
        scripts: { seed: ["python", "seed.py"] }
    }
    ci: Environment{ include: [team_base(), devkit.node(version: "22")] }
}
systems: {                                    // the same modules for a whole machine: JetOS
    laptop: System{ include: [devkit.desktop(), environments.dev] }
}

// shop/env/team.jet: a module is a pure function that returns a value.
team_base :: fn() -[]> Environment {
    Environment{ tools: ["git", "gh"], hooks: { pre_commit: ["jet fmt --check"] } }
}

// shop/env.jet: the expert opt-in. It receives each environment after the
// static data is applied and may read and change anything through core.env.
use core.env.{Env, Service}

env :: fn(e: &Env) -[Net, Fs]> {
    if e.name == "ci" {
        e.services.remove("cache")                         // CI has its own cache
        e.vars.set("CI", "1")
        return
    }
    if e.os == .MacOs -> e.tools.add("colima")              // a container runtime for db
    port := e.services.get("db").port
    if !e.net.port_free(port) -> port = e.net.free_port()
    e.services.get("db").port = port
    e.vars.set("DATABASE_URL", "postgres://127.0.0.1:{port}/shop")
    e.processes.get("web").after(["db"])
    e.on_enter(fn() {
        if !e.fs.exists(".venv") -> e.run(["python", "-m", "venv", ".venv"])
    })
}

// $ jet dev                 static data, then env(e), then services, processes and the loop
// $ jet env show dev        prints the final environment and which line set each value
// $ jet system switch laptop

// core.env, the API env.jet sees (each part has add, remove, get and set):
//   e.name  e.os  e.arch        which environment and machine
//   e.tools                     add("jq"), pin("nodejs", "22.4"), remove
//   e.languages                 node(version:), python(version:, venv:), rust(), ...
//   e.services                  add("db", postgres()), get("db").port, .ready, remove
//   e.processes                 add("web", cmd), get("web").after(["db"]), .restart
//   e.scripts                   add("seed", cmd), run("seed")
//   e.vars                      set, get, unset, path_prepend("bin")
//   e.hooks                     git(.PreCommit, cmd), git_hooks_path
//   e.include(module)           merge a module, by the same rules as include:
//   e.on_enter(fn() { })        logic each time the shell is entered
//   e.run(cmd)  e.fs  e.net     commands, files and ports, only with the effects declared
// A System (JetOS) adds: users, boot, kernel, networking, system services;
// `system :: fn(s: &System)` in env.jet is the same opt-in for machines.

// ===== Best competitor equivalent =====
# devenv.nix: modules for packages, languages, services, processes, scripts and hooks.
{ pkgs, lib, config, ... }: {
  imports = [ ./team.nix ];
  packages = [ pkgs.jq ];
  languages.python = { enable = true; version = "3.12"; venv.enable = true; };
  services.postgres.enable = true;
  processes.web.exec = "npm run dev";
  env.DATABASE_URL = "postgres://127.0.0.1:5432/shop";
  scripts.seed.exec = "python seed.py";
  # Custom logic is Nix expressions over the module options.
  services.redis.enable = lib.mkIf (builtins.getEnv "CI" == "") true;
  enterShell = lib.optionalString config.services.postgres.enable "seed";
}

