// run.jet
#FX(!Net, !FS)
module pricing

// run.jet: the beginner path, the same under every option
fn run() {
    text :: read_file("prices.md")
    print(pricing.total(text))
}

// pricing.jet
fn total(text: String) -> Int {
    sum := 0
    loop line in text.lines() -> sum += Int.parse(line) ?? 0
    sum
}

// a helper that reads a file is refused where it is written:
